fn bytes2u64(s: &[u8], start: usize_t, size: usize_t) -> (ret: u64_t)
    requires
        start < s@.len(),
        size <= s@.len() - start,
        s@.len() < u64::MAX,
        size < 8,
{
    let mut ret: u64_t = 0;
    let mut i = start;
    while i < start + size
        invariant
            start <= i <= start + size,
            start + size <= s@.len(),
            size < 8,
            s@.len() < u64::MAX,
    {
        let c: u64 = (*slice_index_get(s, i)) as u64;
        let offset = (i - start) as u64;
        ret = ret | (c << (offset * 8));
        i = i + 1;
    }
    ret
}

