) -> (ret: (Self, VBox<VmsaPage>))
    requires
        self.wf(),
        (*old(cs)).inv(),
        vmsa.is_vmpl0_private_page(),
        vmsa@.vmpl.spec_eq(vmpl as int),
        nextvmpl_id@.vmpl == vmpl,
