            cs5,
            *cs,
            set![],
            set![spec_ALLOCATOR_lockid(), spec_PT_lockid()],
            set![],
            set![],
        );
    }
    let GhcbHyperPageHandle(bsp_ghcb_h, ap_hyperv_h) = bsp_for_ap_handle;
    ap_hyperv_h.into_raw();  // TODO: pass to ap vmsa.
    GhcbHyperPageHandle(bsp_ghcb_h, bsp_hyperpage_h)
