        }
        i = i + 1;
    }
    proof {
        assert_seqs_equal!(
            ports@.map_values(|p: ContainerPort| model_resource::make_service_port(p@)),
            Seq::new(ports@.len(), |k: int| model_resource::make_service_port(ports[k]@))
        );
    }

    service_ports
}

